#[derive(Serialize)]
struct Project {
id: String,
name: String,
}

let projects: Vec<Project> = Vec::new();
let pagination = PaginationMeta {
total: 0,
page: 1,
per_page: 20,
next_cursor: None,
};

let response = DataResponse::with_pagination(projects, pagination);
// Serializes to: {"data": [...], "pagination": {"total": 100, "page": 1, "per_page": 20}}
```

